  function marketRows(ps){return ps.map(p=>`<div class="market-line"><b onclick="openPlayer('${esc(p.name)}')">${esc(p.name)}<small class="small-muted" style="display:block">${esc(p.club)} · ${p.squad||'1군'} · ${p.position} · 잠재력 ${p.potential}/99</small></b><span>${average(p)}/20</span><button class="btn" onclick="openDeal('${esc(p.name)}')">협상</button></div>`).join('')||'<div class="empty">영입할 선수가 없습니다.</div>'}window.filterMarket=q=>$('#marketPlayers').innerHTML=marketRows(state.players.filter(p=>`${p.name}${p.club}${p.position}`.toLowerCase().includes(q.toLowerCase())&&p.club!==state.clubs[0]?.name));
  // Round-robin fixture generator: each team plays once per matchday, home and away.
  function makeRound(n,md){let names=clubsInLeague(),arr=names.slice();if(arr.length%2)arr.push({name:'BYE',rating:0});let size=arr.length,half=size/2,legs=Math.floor(md/(size-1)),r=md%(size-1);for(let j=0;j<legs*(size-1)+r;j++){arr=[arr[0],arr[size-1],...arr.slice(1,size-1)]}let games=[];for(let i=0;i<half;i++){let a=arr[i],b=arr[size-1-i];if(a.name==='BYE'||b.name==='BYE')continue;let flip=(r+i)%2===1;if(legs%2)flip=!flip;if(flip)[a,b]=[b,a];games.push([a,b])}return games}
  window.simulateSeason=function(){let max=rounds();if(state.round>max){state.round=1;state.fixtures=[];state.season=nextSeason(state.season)}let md=state.round-1,played=makeRound(clubsInLeague().length,md);for(let [a,b]of played){let x=(a.rating+Math.random()*18-9)/26+Math.random()*2,y=(b.rating+Math.random()*18-9)/26+Math.random()*2;state.fixtures.push({home:a.name,away:b.name,hs:Math.max(0,Math.min(6,Math.round(x))),as:Math.max(0,Math.min(6,Math.round(y))),round:state.round})}for(let c of state.clubs.filter(c=>c.league===state.league)){initClub(c);for(let p of state.players.filter(p=>p.club===c.name&&!p.released)){initPlayer(p);let facility=c.facilities[p.squad==='유망주'?'유소년 훈련 시설':'훈련 시설'];if(Math.random()<.025*facility){let keys=Object.keys(p.attributes),k=keys[Math.floor(Math.random()*keys.length)];p.attributes[k]=Math.min(20,p.attributes[k]+1)}}}state.manager.matches+=played.filter(([a,b])=>state.clubs.some(c=>c.name===a.name||c.name===b.name)).length;state.round++;if(state.round>max){let champion=standings()[0];state.activity.push({icon:'🏆',title:`${state.season} 시즌 종료`,note:`${champion.name} 우승 · ${max}라운드`});if(state.clubs.some(c=>c.name===champion.name)){state.manager.titles++;state.manager.rep=Math.min(99,state.manager.rep+10)}}save();render();toast(`${md+1}라운드 완료 · ${played.length}경기`)};
  // Each completed fixture can be replayed in a short text simulation at selectable speed.
  let timer=null,matchRate=1;window.setMatchRate=n=>{matchRate=n};window.watchMatch=function(i){let f=state.fixtures[i];if(!f)return;$('#matchTitle').textContent=`${f.home} vs ${f.away}`;$('#matchScore').textContent='0 : 0';$('#matchMinute').textContent='경기 시작';$('#matchLog').innerHTML='';$('#matchBar').style.width='0%';$('#matchModal').classList.add('open');let minute=0,events=[];for(let m=5;m<90;m+=Math.floor(Math.random()*15)+8){if(Math.random()<.5)events.push({m,text:`⚽ ${m}분 — ${Math.random()<.5?f.home:f.away} 유효 슈팅!`})}let step=()=>{minute=Math.min(90,minute+Math.max(1,Math.round(matchRate)));$('#matchMinute').textContent=minute>=90?'경기 종료':`${minute}분`;$('#matchBar').style.width=`${minute/90*100}%`;for(let e of events.filter(e=>e.m<=minute&&!e.done)){e.done=true;$('#matchLog').insertAdjacentHTML('beforeend',`<div>${e.text}</div>`)}if(minute>=90){clearInterval(timer);$('#matchLog').insertAdjacentHTML('beforeend',`<div>🏁 최종 스코어: ${f.home} ${f.hs} : ${f.as} ${f.away}</div>`);$('#matchScore').textContent=`${f.hs} : ${f.as}`}};if(timer)clearInterval(timer);timer=setInterval(step,2000);window._matchStep=step};window.closeMatch=()=>{clearInterval(timer);$('#matchModal').classList.remove('open')};window.skipMatch=()=>{if(timer)clearInterval(timer);while(+$('#matchBar').style.width.replace('%','')<100)window._matchStep?.()};
  const divisionTiers={'잉글랜드 프리미어리그':['잉글랜드 챔피언십','잉글랜드 리그 원','잉글랜드 리그 투'],'스페인 라리가':['스페인 라리가 2','스페인 프리메라 페데라시온','스페인 세군다 페데라시온'],'이탈리아 세리에 A':['이탈리아 세리에 B','이탈리아 세리에 C A조','이탈리아 세리에 C B조'],'독일 분데스리가':['독일 2. 분데스리가','독일 3. 리가','독일 레기오날리가'],'프랑스 리그 1':['프랑스 리그 2','프랑스 샹피오나 나시오날','프랑스 나시오날 2'],'대한민국 K리그 1':['대한민국 K리그 2','대한민국 K리그 3','대한민국 K리그 4']};
  const cities=['서울','부산','인천','대구','광주','대전','수원','성남','고양','용인','전주','울산','창원','포항','춘천','강릉','파주','안양','김포','천안','청주','목포','여수','원주'],suffix=['유나이티드','시티','FC','아틀레틱','스포츠'];
