  const allClubDefs=()=>Object.entries(leagueTeams).flatMap(([league,teams])=>teams.map(([name,crest,rating])=>({name,crest,rating,league,base:true}))),academyNames=['김민준','이서준','박도윤','최하준','정지후','강시우','조건우','윤현우','장유준','임태민','한지호','오지환','서준혁','신도현','권민재','황재원'],academyPositions=['GK','CB','CB','LB','RB','CDM','CM','CM','CAM','LW','RW','ST'];
